WITH latest AS (SELECT * FROM (SELECT *, RANK() OVER (PARTITION BY category ORDER BY stock_qty DESC) AS row_num FROM products) ranked WHERE row_num = 1) SELECT category, PERCENTILE_APPROX(cost, ARRAY(0.25, 0.5, 0.75)) AS cost_quartiles, CORR(stock_qty, price) AS corr_stock_qty_price, MAX(cost) AS max_cost, BIT_OR(stock_qty) AS stock_qty_bit_or FROM latest GROUP BY ROLLUP (category) ORDER BY category;
